contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        // --- Read-only setup / probes on c's public surface ------------------------
        // We only may use public/external members. C exposes:
        //   c.currentVersion()  -> IOracleProvider.OracleVersion
        //   c.atVersion(uint256)-> IOracleProvider.OracleVersion
        //   c.oracle()          -> IOracleProvider
        //   c.payoffDefinition()-> PayoffDefinition
        // No oracle side-effects can be forced here without a mutable public entry
        // (settle/open/close) that alters c's state.
        //
        // GENERAL RULE: for every finalized oracle version v that c can report,
        // the number returned by atVersion(v) must equal the raw oracle's
        // atVersion(v) transformed by c.payoffDefinition().transform(),
        // and currentVersion() must equal the transform of oracle().currentVersion().
        // We READ both and compare the observable pair, never mutate c.

        IOracleProvider.OracleVersion memory cv = c.currentVersion();
        IOracleProvider.OracleVersion memory rawCurrent = c.oracle().currentVersion();
        PayoffDefinition memory pd = c.payoffDefinition();
        Fixed18 expectedCurrent = pd.transform(rawCurrent.price);

        IOracleProvider.OracleVersion memory av = c.atVersion(cv.version);
        IOracleProvider.OracleVersion memory rawAt = c.oracle().atVersion(cv.version);
        Fixed18 expectedAt = pd.transform(rawAt.price);

        // The public observable invariant: c's reported transformed price matches
        // the payoffDefinition applied to the underlying oracle price for the same
        // version, and the version/timestamp propagate unchanged.
        assert(
            cv.version == rawAt.version
                && cv.timestamp == rawAt.timestamp
                && av.version == rawAt.version
                && av.timestamp == rawAt.timestamp
                && av.price == expectedAt
                && cv.price == expectedCurrent
        );
    }
}

