contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account) public {
        require(account != address(0));

        IOracleProvider.OracleVersion memory cv = c.currentVersion();
        IOracleProvider.OracleVersion memory at = c.atVersion(cv.version);

        bool reverted;
        try c.settleAccount(account) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted
                ? c.latestVersion(account) == cv.version
                : c.latestVersion(account) <= c.latestVersion()
        );

        assert(at.version == cv.version);
    }
}

