contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        UFixed18 makerAmount,
        UFixed18 takerAmount,
        IOracleProvider oracle_,
        uint256 oracleVersion
    ) public {
        // A completed call through c's public surface, using observable inputs.
        c.atVersion(oracleVersion);

        Position memory p = Position({maker: makerAmount, taker: takerAmount});
        Fixed18 r = c.rate(p);

        // General rule: the reported rate must be the utilization-curve rate for
        // the utilization of the passed position, divided by 365 days (the only
        // arithmetic relationship exposed by the public surface).
        UFixed18 utilization = makerAmount == UFixed18Lib.ZERO
            ? UFixed18Lib.MAX
            : takerAmount.div(makerAmount);
        JumpRateUtilizationCurve memory curve = c.utilizationCurve();
        Fixed18 expected = curve.compute(utilization).div(Fixed18Lib.from(365 days));

        assert(Fixed18.unwrap(r) == Fixed18.unwrap(expected));
    }
}

